+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limit = parseLimit(message.limit);
+  if (!limit.ok) return {valid: false, error: limit.error};
+
+  const before = parseBeforeCursor(message.before);
+  if (!before.ok) return {valid: false, error: before.error};
+
+  return {
+    valid: true,
+    data: {
+      type: 'list_sessions',
+      ...(limit.value === undefined ? {} : {limit: limit.value}),
+      ...(before.value === undefined ? {} : {before: before.value}),
+    },
+  };
+}
+
+type ParsedField<T> = {ok: true; value: T} | {ok: false; error: string};
+
+function parseLimit(limit: unknown): ParsedField<number | undefined> {
+  if (limit === undefined) return {ok: true, value: undefined};
+  if (typeof limit === 'number' && Number.isInteger(limit) && limit >= 0) return {ok: true, value: limit};
+  return {ok: false, error: 'list_sessions limit must be a non-negative integer'};
+}
+
+function parseBeforeCursor(before: unknown): ParsedField<SessionCursor | undefined> {
+  if (before === undefined) return {ok: true, value: undefined};
+  if (typeof before !== 'object' || before === null) {
+    return {ok: false, error: 'list_sessions before must be an object'};
+  }
+  const cursor = before as Record<string, unknown>;
+  if (!isValidSessionId(cursor.sessionId)) {
+    return {ok: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
+  }
+  if (!isValidUpdatedAt(cursor.updatedAt)) {
+    return {ok: false, error: 'list_sessions before.updatedAt must be a valid date string or timestamp'};
+  }
+  return {
+    ok: true,
+    value: {
+      updatedAt: cursor.updatedAt,
+      sessionId: cursor.sessionId,
+    },
+  };
+}
+
+function isValidSessionId(sessionId: unknown): sessionId is string {
+  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function isValidUpdatedAt(updatedAt: unknown): updatedAt is string | number {
+  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
+  return Number.isFinite(new Date(updatedAt).getTime());
+}
